func (h chatServiceHandler) unarchive(ctx context.Context, _ connect.Spec, stream connect.ServerStream) error {
	var req v1.UnarchiveRequest
	if err := stream.Receive(&req); err != nil {
		return err
	}
	res, err := h.svc.Unarchive(ctx, &req)
	if err != nil {
		return err
	}
	return stream.Send(res)
}

func (h chatServiceHandler) watchChat(ctx context.Context, _ connect.Spec, stream connect.ServerStream) error {
	var req v1.WatchChatRequest
	if err := stream.Receive(&req); err != nil {
		return err
	}
	return h.svc.WatchChat(ctx, &req, ChatServiceWatchChatServerStream{stream: stream})
}
